package com.moishow.identity;
import com.moishow.MoishowServerApplication;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.web.server.context.WebServerApplicationContext;import org.springframework.context.ConfigurableApplicationContext;import org.springframework.context.annotation.*;
import org.testcontainers.postgresql.PostgreSQLContainer;import tools.jackson.databind.*;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.concurrent.*;

class ProfileApiTest {
 static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");static ConfigurableApplicationContext context;static String base;static ObjectMapper json=new ObjectMapper();static HttpClient http=HttpClient.newHttpClient();static Map<String,String> codes=new ConcurrentHashMap<>();
 @org.junit.jupiter.api.io.TempDir static java.nio.file.Path storage;
 record Reply(int status,JsonNode body){}
 @Configuration @Profile("profile-test") static class Providers {
  @Bean @Primary SocialVerifier fixtureIdentity(){return (provider,token,nonce)->{ApiProblem.require(token.startsWith("profile-test:"),401,"INVALID_SOCIAL_TOKEN");return new SocialVerifier.Identity(provider,token.substring(13));};}
  @Bean @Primary SmsGateway captureSms(){return (phone,code)->codes.put(phone,code);}
 }
 @BeforeAll static void start(){postgres.start();context=new SpringApplicationBuilder(MoishowServerApplication.class,Providers.class).profiles("db","dev","profile-test").properties("server.port=0","logging.level.root=ERROR","spring.main.banner-mode=off").run("--FILE_STORAGE_MODE=LOCAL","--FILE_STORAGE_ROOT="+storage,"--spring.datasource.url="+postgres.getJdbcUrl(),"--spring.datasource.username="+postgres.getUsername(),"--spring.datasource.password="+postgres.getPassword());base="http://127.0.0.1:"+((WebServerApplicationContext)context).getWebServer().getPort()+"/api/v1";}
 @AfterAll static void stop(){if(context!=null)context.close();postgres.stop();}
 static Reply call(String method,String path,String token,Object data,String key)throws Exception{var b=HttpRequest.newBuilder(URI.create(base+path)).header("Content-Type","application/json");if(token!=null)b.header("Authorization","Bearer "+token);if(key!=null)b.header("Idempotency-Key",key);b.method(method,data==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(data)));var response=http.send(b.build(),HttpResponse.BodyHandlers.ofString());return new Reply(response.statusCode(),response.body().isBlank()?json.createObjectNode():json.readTree(response.body()));}
 static Reply post(String path,String token,Object body)throws Exception{return call("POST",path,token,body,UUID.randomUUID().toString());}static Reply get(String path,String token)throws Exception{return call("GET",path,token,null,null);}
 static String user(String name)throws Exception{var challenge=post("/auth/challenges",null,Map.of());var login=post("/auth/social",null,Map.of("provider","GOOGLE","token","profile-test:"+name,"challengeId",challenge.body.path("challengeId").asText()));assertEquals(200,login.status);String pending=login.body.path("token").asText(),phone="+8210"+String.format("%08d",Math.floorMod(name.hashCode(),100000000));var sms=post("/auth/sms",pending,Map.of("phone",phone));assertEquals(200,sms.status);assertEquals(200,post("/auth/sms/"+sms.body.path("id").asText()+"/verify",pending,Map.of("code",codes.get(phone))).status);var registered=post("/auth/register",pending,Map.of("nickname",name,"verificationId",sms.body.path("id").asText()));assertEquals(200,registered.status);return registered.body.path("token").asText();}
 static long version(String token)throws Exception{return get("/me",token).body.path("version").asLong();}
 static String photo(String token,String club)throws Exception{String boundary="profile-"+UUID.randomUUID();var out=new java.io.ByteArrayOutputStream();out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"scope\"\r\n\r\nPOST\r\n").getBytes(StandardCharsets.UTF_8));if(club!=null)out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"clubId\"\r\n\r\n"+club+"\r\n").getBytes(StandardCharsets.UTF_8));out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"profile.png\"\r\nContent-Type: image/png\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a9wAAAABJRU5ErkJggg=="));out.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));var response=http.send(HttpRequest.newBuilder(URI.create(base+"/files")).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID().toString()).header("Content-Type","multipart/form-data; boundary="+boundary).POST(HttpRequest.BodyPublishers.ofByteArray(out.toByteArray())).build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,response.statusCode(),response.body());return json.readTree(response.body()).path("id").asText();}
 @Test void optionalMetadataPersistsTrimsDeduplicatesAndPreservesUnspecifiedFields()throws Exception{String token=user("프로필 주인");var before=get("/me/profile",token);assertEquals(200,before.status);String id=before.body.path("id").asText();var changed=post("/me/profile",token,Map.of("version",version(token),"interests",List.of(" 산책 ","운동","산책"),"bio","함께 걷는 시간을 좋아해요"));assertEquals(200,changed.status,changed.body.toString());assertEquals(List.of("산책","운동"),json.convertValue(changed.body.path("interests"),List.class));assertEquals("프로필 주인",changed.body.path("nickname").asText());var renamed=post("/me/profile",token,Map.of("version",version(token),"nickname","새 닉네임"));assertEquals(200,renamed.status);assertEquals(id,renamed.body.path("id").asText());assertEquals("함께 걷는 시간을 좋아해요",renamed.body.path("bio").asText());assertEquals(2,renamed.body.path("interests").size());var clear=post("/me/profile",token,Map.of("version",version(token),"interests",List.of(),"bio",""));assertEquals(200,clear.status);assertEquals(0,clear.body.path("interests").size());assertEquals("",clear.body.path("bio").asText());}
 @Test void avatarIsOwnPersonalPostPhotoAndDoesNotBecomePublic()throws Exception{String owner=user("사진 주인"),other=user("다른 사진 주인");String file=photo(owner,null);var saved=post("/me/profile",owner,Map.of("version",version(owner),"avatarFileId",file));assertEquals(200,saved.status,saved.body.toString());assertEquals(file,saved.body.path("avatarFileId").asText());assertEquals(403,http.send(HttpRequest.newBuilder(URI.create(base+"/files/"+file)).header("Authorization","Bearer "+other).GET().build(),HttpResponse.BodyHandlers.ofByteArray()).statusCode());String foreign=photo(other,null);assertEquals(403,post("/me/profile",owner,Map.of("version",version(owner),"avatarFileId",foreign)).status);String club=post("/clubs",owner,Map.of("name","사진 모임","joinMode","IMMEDIATE")).body.path("id").asText();String clubPhoto=photo(owner,club);assertEquals(403,post("/me/profile",owner,Map.of("version",version(owner),"avatarFileId",clubPhoto)).status);assertEquals(file,get("/me/profile",owner).body.path("avatarFileId").asText());var clear=post("/me/profile",owner,Map.of("version",version(owner),"clearAvatar",true));assertEquals(200,clear.status);assertTrue(clear.body.path("avatarFileId").isNull());}
 @Test void metadataValidationStaleVersionAndReplayDoNotChangeAnotherUser()throws Exception{String token=user("검증 프로필"),other=user("별개 프로필");long version=version(token);assertEquals(400,post("/me/profile",token,Map.of("version",version,"interests",List.of("가".repeat(31)))).status);assertEquals(400,post("/me/profile",token,Map.of("version",version,"bio","나".repeat(301))).status);assertEquals(400,post("/me/profile",token,Map.of("version",version,"interests",java.util.stream.IntStream.range(0,21).mapToObj(i->"관심"+i).toList())).status);String key=UUID.randomUUID().toString();var input=Map.of("version",version,"nickname","보존 이름","bio","저장 내용");var first=call("POST","/me/profile",token,input,key);assertEquals(200,first.status);assertEquals(first.body,call("POST","/me/profile",token,input,key).body);assertEquals(409,post("/me/profile",token,Map.of("version",version,"nickname","오래된 수정")).status);assertEquals("별개 프로필",get("/me/profile",other).body.path("nickname").asText());}
}
